BEGIN;
DO $p$ DECLARE d text; d0 text; BEGIN d := pg_get_functiondef('public.lf_profile_execution_begin_from_handoff_v1(jsonb,text,text,text,text,text,text,jsonb)'::regprocedure); d0 := d; d := regexp_replace(d, $r$v_repair_write boolean:=false;(\s+)BEGIN$r$, E'v_repair_write boolean:=false;\n  v_prev jsonb;\n  v_src text:=nullif(p_handoff#>>''{scope,source_execution_id}'','''');\nBEGIN'); d := replace(d, 'v_begin:=public.lf_profile_execution_begin_v1(', $q$IF v_src IS NOT NULL THEN SELECT jsonb_build_array(jsonb_build_object('execution_id',v_src,'output_ref',s.evidence_ref,'deliverable_sha256',s.evidence_payload->>'raw_output_sha256','summary',left(coalesce(s.evidence_payload#>>'{profile_output,summary}',s.evidence_payload->>'step_result',''),500))) INTO v_prev FROM public.lf_operation_execution_steps s WHERE s.execution_id=v_src AND s.step_id='execute_profile' AND s.status='STEP_PASS_WITH_EVIDENCE' AND s.evidence_ref IS NOT NULL ORDER BY s.observed_at DESC LIMIT 1; IF v_prev IS NULL THEN RETURN jsonb_build_object('status','BLOCKED','blocking_code','BLOCK_PREVIOUS_OUTPUTS_MISSING','source_execution_id',v_src); END IF; END IF; v_begin:=public.lf_profile_execution_begin_v1($q$); d := replace(d, $s$'no_promotion',true,$s$, $s$'previous_outputs',coalesce(v_prev,'[]'::jsonb),'no_promotion',false,$s$); IF d = d0 OR position('BLOCK_PREVIOUS_OUTPUTS_MISSING' in d)=0 OR position('''no_promotion'',false' in d)=0 OR position('v_prev jsonb' in d)=0 THEN RAISE EXCEPTION 'LF_PREVIOUS_OUTPUTS_PATCH_NOT_APPLIED'; END IF; EXECUTE d; END $p$;
COMMIT;
